def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue

            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))

            r0 = min(x for x, y in cells)
            r1 = max(x for x, y in cells)
            c0 = min(y for x, y in cells)
            c1 = max(y for x, y in cells)

            perimeter = {
                (rr, cc)
                for rr in range(r0, r1 + 1)
                for cc in range(c0, c1 + 1)
                if rr in (r0, r1) or cc in (c0, c1)
            }
            if (set(cells) == perimeter and r1 - r0 >= 2 and c1 - c0 >= 2):
                fill = 7 if (r1 - r0 == 2 and c1 - c0 == 2) else 2
                for rr in range(r0 + 1, r1):
                    for cc in range(c0 + 1, c1):
                        if grid[rr][cc] == bg:
                            out[rr][cc] = fill

    return out
